package scoretype

import (
	"bytes"
	"encoding/json"
	"os"
	"reflect"
	"strconv"
	"testing"
)

// goldenCase is a case of testdata/upstream_golden.json: the output of the
// score types of CMS itself (generated by testdata/gen_golden.py).
type goldenCase struct {
	Name        string          `json:"name"`
	ScoreType   string          `json:"score_type"`
	Parameters  json.RawMessage `json:"parameters"`
	Public      map[string]bool `json:"public"`
	Precision   int             `json:"precision"`
	TimeLimit   *float64        `json:"time_limit"`
	Evaluated   *bool           `json:"evaluated"`
	Evaluations []struct {
		Codename string   `json:"codename"`
		Outcome  string   `json:"outcome"`
		Text     []string `json:"text"`
		Time     *float64 `json:"time"`
		Memory   *int64   `json:"memory"`
	} `json:"evaluations"`

	Error          string          `json:"error"`
	MaxScore       float64         `json:"max_score"`
	MaxPublicScore float64         `json:"max_public_score"`
	RankingHeaders []string        `json:"ranking_headers"`
	Score          float64         `json:"score"`
	Details        json.RawMessage `json:"details"`
	PublicScore    float64         `json:"public_score"`
	PublicDetails  json.RawMessage `json:"public_details"`
	RankingDetails []string        `json:"ranking_details"`

	raw map[string]json.RawMessage
}

func loadGolden(t *testing.T) []goldenCase {
	t.Helper()
	b, err := os.ReadFile("testdata/upstream_golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []goldenCase
	if err := json.Unmarshal(b, &cases); err != nil {
		t.Fatal(err)
	}
	var raws []map[string]json.RawMessage
	if err := json.Unmarshal(b, &raws); err != nil {
		t.Fatal(err)
	}
	for i := range cases {
		cases[i].raw = raws[i]
	}
	return cases
}

func (c *goldenCase) submissionResult(t *testing.T) *SubmissionResult {
	sr := &SubmissionResult{Evaluated: c.Evaluated == nil || *c.Evaluated, TimeLimit: c.TimeLimit}
	for _, e := range c.Evaluations {
		o, err := strconv.ParseFloat(e.Outcome, 64)
		if err != nil {
			t.Fatal(err)
		}
		sr.Evaluations = append(sr.Evaluations, Evaluation{
			Codename: e.Codename, Outcome: o, Text: e.Text, ExecutionTime: e.Time, ExecutionMemory: e.Memory,
		})
	}
	return sr
}

// sameJSON compares two JSON documents as values (numbers as float64, so
// 40 and 40.0 are equal, key order does not matter).
func sameJSON(t *testing.T, what string, got, want []byte) {
	t.Helper()
	var g, w any
	if err := json.Unmarshal(got, &g); err != nil {
		t.Fatalf("%s: invalid JSON %s: %v", what, got, err)
	}
	if err := json.Unmarshal(want, &w); err != nil {
		t.Fatalf("%s: invalid golden JSON %s: %v", what, want, err)
	}
	if !reflect.DeepEqual(g, w) {
		t.Errorf("%s:\n got %s\nwant %s", what, got, want)
	}
}

// TestUpstreamGolden compares the score types with the output of CMS on the
// same inputs: max scores, ranking headers, scores, details, public
// details, ranking details and the details filtered for each feedback
// level.
func TestUpstreamGolden(t *testing.T) {
	for _, c := range loadGolden(t) {
		t.Run(c.Name, func(t *testing.T) {
			st, err := New(c.ScoreType, c.Parameters, c.Public, c.Precision)
			if c.Error == "new" {
				if err == nil {
					t.Fatalf("New(%s) succeeded, CMS fails", c.Parameters)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if st.MaxScore() != c.MaxScore || st.MaxPublicScore() != c.MaxPublicScore {
				t.Errorf("max scores %v, %v; want %v, %v", st.MaxScore(), st.MaxPublicScore(), c.MaxScore, c.MaxPublicScore)
			}
			if h := st.RankingHeaders(); !reflect.DeepEqual(h, c.RankingHeaders) {
				t.Errorf("headers %q, want %q", h, c.RankingHeaders)
			}
			if _, ok := c.raw["evaluations"]; !ok {
				return
			}
			r, err := st.ComputeScore(c.submissionResult(t))
			if c.Error == "compute" {
				if err == nil {
					t.Fatal("ComputeScore succeeded, CMS fails")
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if r.Score != c.Score || r.PublicScore != c.PublicScore {
				t.Errorf("scores %v, %v; want %v, %v", r.Score, r.PublicScore, c.Score, c.PublicScore)
			}
			if !reflect.DeepEqual(r.RankingDetails, c.RankingDetails) {
				t.Errorf("ranking details %q, want %q", r.RankingDetails, c.RankingDetails)
			}
			details, _ := json.Marshal(r.Details)
			public, _ := json.Marshal(r.PublicDetails)
			sameJSON(t, "details", details, c.Details)
			sameJSON(t, "public details", public, c.PublicDetails)

			for _, which := range []struct {
				name      string
				ours, cms []byte
			}{{"details", details, c.Details}, {"public_details", public, c.PublicDetails}} {
				for _, level := range []FeedbackLevel{FeedbackFull, FeedbackRestricted, FeedbackOIRestricted} {
					key := "json_" + which.name + "_" + string(level)
					want := c.raw[key]
					// Filter both our details and the ones written by CMS.
					for _, src := range [][]byte{which.ours, which.cms} {
						d, err := st.JSONDetails(src, level)
						if err != nil {
							t.Fatalf("%s: %v", key, err)
						}
						got, _ := json.Marshal(d)
						sameJSON(t, key, got, want)
					}
				}
			}
		})
	}
}

func TestGoldenCoversFix(t *testing.T) {
	// The golden file must exercise the cases where CMS fails to filter the
	// public details (see filterGroup).
	n := 0
	for _, c := range loadGolden(t) {
		for k := range c.raw {
			if bytes.HasSuffix([]byte(k), []byte("_fixed")) {
				n++
			}
		}
	}
	if n == 0 {
		t.Fatal("no case with a subtask without score in the public details")
	}
}
